"""Persisted, cross-domain recommendations generated by Analytics."""

import json
from dataclasses import dataclass
from typing import Any

from sqlalchemy import text
from sqlalchemy.ext.asyncio import AsyncSession


@dataclass(frozen=True)
class RecommendationDraft:
    """A recommendation with its supporting evidence."""

    fingerprint: str
    category: str
    severity: str
    confidence: float
    title: str
    summary: str
    recommendation: str
    evidence: dict[str, Any]


async def refresh_recommendations(session: AsyncSession, database_id: int) -> int:
    """Generate and upsert the currently supported database recommendations."""
    drafts = await _find_table_maintenance(session, database_id)
    drafts.extend(await _find_unused_indexes(session, database_id))
    drafts.extend(await _find_missing_indexes(session, database_id))
    capacity = await _find_capacity_fit(session, database_id)
    if capacity is not None:
        drafts.append(capacity)
    for draft in drafts:
        await _upsert(session, database_id, draft)
    return len(drafts)


async def _find_table_maintenance(session: AsyncSession, database_id: int) -> list[RecommendationDraft]:
    result = await session.execute(text("""
        SELECT table_id, schema_name, name, n_live_tup, n_dead_tup, last_vacuum, last_autovacuum
        FROM (
            SELECT DISTINCT ON (t.id) t.id AS table_id, t.schema_name, t.name,
                   m.n_live_tup, m.n_dead_tup, m.last_vacuum, m.last_autovacuum
            FROM metadata.table t JOIN metric.table m ON m.table_id = t.id
            WHERE t.database_id = :database_id AND t.deleted_at IS NULL
            ORDER BY t.id, m.collected_at DESC
        ) latest
        WHERE n_dead_tup >= 10000 AND n_dead_tup::float / GREATEST(n_live_tup, 1) >= 0.20
    """), {"database_id": database_id})
    return [
        RecommendationDraft(
            fingerprint=f"vacuum:{row.table_id}", category="maintenance", severity="warning",
            confidence=0.78, title=f"Vacuum may be needed for {row.schema_name}.{row.name}",
            summary="Dead tuples exceed 20% of live tuples, which can increase scan cost.",
            recommendation="Review autovacuum and consider VACUUM (ANALYZE) outside peak traffic.",
            evidence={"table_id": row.table_id, "table": f"{row.schema_name}.{row.name}",
                      "live_tuples": row.n_live_tup, "dead_tuples": row.n_dead_tup,
                      "dead_tuple_ratio": round(row.n_dead_tup / max(row.n_live_tup or 0, 1), 4),
                      "last_vacuum": _iso(row.last_vacuum), "last_autovacuum": _iso(row.last_autovacuum)},
        ) for row in result.mappings()
    ]


async def _find_unused_indexes(session: AsyncSession, database_id: int) -> list[RecommendationDraft]:
    result = await session.execute(text("""
        SELECT index_id, schema_name, table_name, index_name, size, scan_qt
        FROM (
            SELECT DISTINCT ON (i.id) i.id AS index_id, t.schema_name, t.name AS table_name,
                   i.name AS index_name, m.size, m.scan_qt
            FROM metadata.index i JOIN metadata.table t ON t.id = i.table_id
            JOIN metric.index m ON m.index_id = i.id
            WHERE i.database_id = :database_id AND i.deleted_at IS NULL AND t.deleted_at IS NULL
              AND NOT i.is_primary AND NOT i.is_unique
            ORDER BY i.id, m.collected_at DESC
        ) latest
        WHERE size >= 67108864 AND COALESCE(scan_qt, 0) = 0
    """), {"database_id": database_id})
    return [
        RecommendationDraft(
            fingerprint=f"unused-index:{row.index_id}", category="index", severity="info",
            confidence=0.72, title=f"Review unused index {row.index_name}",
            summary="This non-unique index is at least 64 MB and has no recorded scans.",
            recommendation="Validate workload and retention needs before dropping the index.",
            evidence={"index_id": row.index_id, "table": f"{row.schema_name}.{row.table_name}",
                      "index": row.index_name, "size_bytes": row.size, "scan_count": row.scan_qt},
        ) for row in result.mappings()
    ]


async def _find_missing_indexes(session: AsyncSession, database_id: int) -> list[RecommendationDraft]:
    result = await session.execute(text("""
        SELECT DISTINCT ON (title) title, confidence, explanation, recommendation, evidence
        FROM analytics.query_analysis_finding finding
        JOIN analytics.query_analysis analysis ON analysis.id = finding.analysis_id
        WHERE analysis.database_id = :database_id AND finding.type = 'missing_index'
        ORDER BY title, finding.created_at DESC
        LIMIT 20
    """), {"database_id": database_id})
    drafts = []
    for row in result.mappings():
        evidence = row.evidence or {}
        table = evidence.get("table", "the affected table")
        columns = evidence.get("missing_prefix_columns", [])
        column_text = ", ".join(columns) if columns else "the filtered columns"
        drafts.append(
            RecommendationDraft(
                fingerprint=f"missing-index:{table}:{column_text}", category="index",
                severity="warning", confidence=float(row.confidence),
                title=f"Possible missing index on {table}",
                summary=f"Queries filter on {column_text}, but no matching index prefix was found.",
                recommendation="Validate a matching index with EXPLAIN before applying it in production.",
                evidence=evidence,
            )
        )
    return drafts


async def _find_capacity_fit(session: AsyncSession, database_id: int) -> RecommendationDraft | None:
    result = await session.execute(text("""
        SELECT AVG(cpu.cpu_percent) AS avg_cpu, MAX(cpu.cpu_percent) AS max_cpu, COUNT(cpu.cpu_percent) AS cpu_samples,
               AVG(ram.percent) AS avg_ram, MAX(ram.percent) AS max_ram, COUNT(ram.percent) AS ram_samples
        FROM metadata.database db
        LEFT JOIN metric.cpu cpu ON cpu.server_id = db.server_id AND cpu.collected_at >= NOW() - INTERVAL '30 days'
        LEFT JOIN metric.ram ram ON ram.server_id = db.server_id AND ram.collected_at >= NOW() - INTERVAL '30 days'
        WHERE db.id = :database_id
        GROUP BY db.id
    """), {"database_id": database_id})
    row = result.mappings().one_or_none()
    if not row or min(row.cpu_samples or 0, row.ram_samples or 0) < 24:
        return None
    if any(value is None for value in (row.avg_cpu, row.max_cpu, row.avg_ram, row.max_ram)):
        return None
    if row.avg_cpu >= 20 or row.max_cpu >= 45 or row.avg_ram >= 55 or row.max_ram >= 75:
        return None
    return RecommendationDraft(
        fingerprint="capacity-fit:overprovisioned", category="capacity", severity="info", confidence=0.7,
        title="Server may be overprovisioned", summary="CPU and memory remained below conservative thresholds over 30 days.",
        recommendation="Confirm peak and seasonal workload before reducing server resources.",
        evidence={"period_days": 30, "cpu_avg_percent": round(row.avg_cpu, 2), "cpu_max_percent": round(row.max_cpu, 2),
                  "ram_avg_percent": round(row.avg_ram, 2), "ram_max_percent": round(row.max_ram, 2),
                  "cpu_samples": row.cpu_samples, "ram_samples": row.ram_samples},
    )


async def _upsert(session: AsyncSession, database_id: int, draft: RecommendationDraft) -> None:
    await session.execute(text("""
        INSERT INTO analytics.recommendation
            (database_id, fingerprint, category, severity, confidence, title, summary, recommendation, evidence)
        VALUES (:database_id, :fingerprint, :category, :severity, :confidence, :title, :summary,
                :recommendation, CAST(:evidence AS jsonb))
        ON CONFLICT (database_id, fingerprint) DO UPDATE SET
            category = EXCLUDED.category, severity = EXCLUDED.severity, confidence = EXCLUDED.confidence,
            title = EXCLUDED.title, summary = EXCLUDED.summary, recommendation = EXCLUDED.recommendation,
            evidence = EXCLUDED.evidence, last_seen_at = NOW(),
            status = CASE WHEN analytics.recommendation.status = 'dismissed' THEN 'dismissed' ELSE 'open' END
    """), {"database_id": database_id, **draft.__dict__, "evidence": json.dumps(draft.evidence, default=str)})
    if draft.severity == "critical":
        await _notify_critical(session, database_id, draft)


async def _notify_critical(
    session: AsyncSession,
    database_id: int,
    draft: RecommendationDraft,
) -> None:
    await session.execute(text("""
        INSERT INTO notifier.notification (message, params)
        SELECT :message, jsonb_build_object(
            'path', '/analytics/' || database.public_id::text || '/recommendations',
            'source', 'analytics recommendations',
            'scope', 'database',
            'type', 'recommendation',
            'database_id', :database_id,
            'fingerprint', :fingerprint,
            'category', :category,
            'severity', 'critical'
        )
        FROM metadata.database AS database
        WHERE database.id = :database_id
          AND NOT EXISTS (
              SELECT 1
              FROM notifier.notification AS notification
              WHERE notification.params->>'source' = 'analytics recommendations'
                AND notification.params->>'database_id' = CAST(:database_id AS text)
                AND notification.params->>'fingerprint' = :fingerprint
          )
    """), {
        "message": f"Critical analytics recommendation: {draft.title}",
        "database_id": database_id,
        "fingerprint": draft.fingerprint,
        "category": draft.category,
    })


def _iso(value: Any) -> str | None:
    return value.isoformat() if value else None
